import React from "react"
import { QuotaBar } from "@sb-components/starci/blocks/ai/QuotaBar/QuotaBar"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaLane` — one lane's pair of rolling-window quota bars ("next 5 hours"
 * above "this week"), shared by the Auto tab and the Premium branch of the
 * Subscription tab inside `AiQuotaModal`. Both rows are the same `QuotaBar`
 * composition reading a different window. Unset `data`/`isLoading` shimmers
 * both bars.
 */

/** One rolling-window quota reading, ready to draw as a single {@link ProgressBar}. */
export interface AiQuotaWindow {
    /** Amount consumed in this window. */
    used: number
    /** Cap for this window (`0` reads as "no allowance"). */
    limit: number
    /** Reset line under the bar (e.g. `"Resets at 18:50 on 06/01"`). `null`/unset → no line. */
    resetLabel?: string | null
}

/** The two rolling windows one {@link AiQuotaLane} tracks. */
export interface AiQuotaLaneData {
    /** Next-5-hours rolling window. */
    window5h: AiQuotaWindow
    /** This-week rolling window. */
    windowWeek: AiQuotaWindow
}

/** Props for {@link AiQuotaLane}. */
export interface AiQuotaLaneProps {
    /** The lane's two windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → this lane's own fetch is in flight; both bars draw their skeleton mirror. */
    isLoading: boolean
}

/**
 * The lane's two bars. See the file header for what it owns (window labels)
 * and what it deliberately does not (fetching — `data` is a plain prop, never
 * an internal SWR call — and the fill-tone ramp, which `QuotaBar` owns).
 *
 * @param props - {@link AiQuotaLaneProps}
 */
const AiQuotaLane = ({ data, isLoading }: AiQuotaLaneProps) => {
    const showSkeleton = isLoading || !data

    return (
        <div>
            <StackV gap={4} items={[
                () => (
                    <QuotaBar
                        label="Next 5 hours"
                        used={data?.window5h.used ?? 0}
                        limit={data?.window5h.limit ?? 0}
                        resetLabel={data?.window5h.resetLabel}
                        isSkeleton={showSkeleton}


                    />
                ),
                () => (
                    <QuotaBar
                        label="This week"
                        used={data?.windowWeek.used ?? 0}
                        limit={data?.windowWeek.limit ?? 0}
                        resetLabel={data?.windowWeek.resetLabel}
                        isSkeleton={showSkeleton}


                    />
                ),
            ]} />
        </div>
    )
}

export { AiQuotaLane }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` — the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (§12b) — the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited → renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) — an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` — this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <HeroSkeleton className="h-4 w-64 max-w-full rounded" />
    }
    // no seat cap at this phase → no honest scarcity reason → stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` — the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ⇒ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `·` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // §5a: icon matches the FONT-SIZE of the text beside it — `sm`
                        // (14px) ⇒ `size-3.5`. §5.0a: below `size-5` ⇒ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) — but they're still TWO SEPARATE cluster items, since the
                    // `·` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}₫ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` — single-component namespace ⇒ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

import React from "react"
import { BuildingsIcon, LockIcon } from "@phosphor-icons/react"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ConsultantProfileBody` — the full detail content of one consultant's profile:
 * photo, name+role, a pressable company row, the full bio, and either real
 * contact links once unlocked or a locked callout with a way to unlock them.
 * The detail sibling of `ConsultantCard`. `contactUnlocked` only changes which
 * content fills the last slot, not the outer frame.
 */

/** One way to reach this consultant once contact is unlocked — plain navigable data. */
export interface ConsultantProfileBodyContactLink {
    /** Stable React key. */
    key: string
    /** Display label, e.g. "hoa.nguyen@techcorp.vn" or "090 123 4567". */
    label: string
    /** Where the link goes — `mailto:`/`tel:`/`https:` etc. The atom renders it, never fetches it. */
    href: string
    /** Optional leading glyph (mail/phone/chat) as a COMPONENT, not JSX. */
    icon?: TypographyIcon
}

/** One consultant's full profile — plain data, the block builds the detail view from it. */
export interface ConsultantProfileBodyConsultant {
    /** Full name — the profile's accessible heading. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. The company row disappears when absent. */
    companyTitle?: string
    /** Full bio — rendered in full here, unlike `ConsultantCard`'s clamped teaser. */
    description?: string
    /** Photo URL. Empty/missing → `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
    /** `true` → real `contactLinks` are shown. `false` → the locked callout is shown instead. */
    contactUnlocked: boolean
    /** Ways to reach this consultant. Only read when `contactUnlocked` is `true`. */
    contactLinks?: Array<ConsultantProfileBodyContactLink>
}

/** Props for {@link ConsultantProfileBody}. */
export interface ConsultantProfileBodyProps {
    /** The consultant whose profile this fills. */
    consultant: ConsultantProfileBodyConsultant
    /** Fired when the visitor presses the company row. Row is disabled without it. */
    onOpenCompany?: () => void
    /** Fired from the locked callout's CTA. No CTA renders without it. */
    onImproveCv?: () => void
    /**
     * `true` → `Image` and every `Typography` line switch to their own shimmer, the
     * company button is disabled, and the contact fork shows a neutral shimmer
     * instead of picking a branch (see file header). There is no id to open yet.
     */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-contact callout — block-owned wording (§14d.1), see file header. */
const LOCKED_TITLE = "Contact is locked"
const LOCKED_DESCRIPTION = "Improve your CV to unlock this consultant's contact information."
const LOCKED_CTA_LABEL = "Improve CV"

/**
 * The full profile-detail content for one consultant. See the file header for
 * the full contract, the fork between `ConsultantCard`'s tile shape and this
 * one, and the judgment calls behind the contact fork.
 *
 * @param props - {@link ConsultantProfileBodyProps}
 */
const ConsultantProfileBody = ({
    consultant,
    onOpenCompany,
    onImproveCv,
    isSkeleton = false,
}: ConsultantProfileBodyProps) => {
    const { fullName, jobTitle, companyTitle, description, avatarUrl, contactUnlocked, contactLinks } = consultant

    const nameRow = (
        <StackV gap={1} align="center" principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
            isSkeleton={isSkeleton} items={[
                () => (
                    <Typography
                        size="h4"
                        weight="bold"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={fullName}

                    />
                ),
                ...(isSkeleton || jobTitle ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={jobTitle}

                    />
                )] : []),
            ]} />
    )

    // identity: centered photo, name+role, pressable company row
    const identity = (
        <StackV gap={4} align="center" principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            isSkeleton={isSkeleton} items={[
                () => (
                    <div className="w-28">
                        <Image
                            src={avatarUrl}
                            alt={fullName}
                            ratio="square"
                            radius="full"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                () => nameRow,
                ...(isSkeleton || companyTitle ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="sm"
                        label={companyTitle ?? ""}
                        prefixIcon={BuildingsIcon}
                        onPress={onOpenCompany}
                        isDisabled={isSkeleton || !onOpenCompany}

                    />
                )] : []),
            ]} />
    )

    // contact fork — see file header for why loading shimmers neutrally
    const contactFork = isSkeleton ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={[
            () => <Typography size="sm" isSkeleton />,
            () => <Typography size="sm" isSkeleton />,
        ]} />
    ) : contactUnlocked ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={(contactLinks ?? []).map((link) => () => (
            <Typography
                size="sm"
                isLink
                href={link.href}
                prefixIcon={link.icon}
                text={link.label}

            />
        ))} />
    ) : (
        <Callout
            status="warning"
            icon={LockIcon}
            title={LOCKED_TITLE}
            description={LOCKED_DESCRIPTION}
            actionLabel={onImproveCv ? LOCKED_CTA_LABEL : undefined}
            onAction={onImproveCv}


        />
    )

    return (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ConsultantProfileBody" }}
            items={[
                () => identity,
                // full bio — no clamp, unlike ConsultantCard's directory teaser
                ...(isSkeleton || description ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}

                    />
                )] : []),
                () => contactFork,
            ]}
        />
    )
}

export { ConsultantProfileBody }

import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `CourseQaEngagementStrip`: the "you're not learning alone" honest
 * aggregate under `CourseQaHeader` on a course Q&A board — enrolled learners,
 * then answered/total questions. See the component file header for the full
 * real-numbers-only contract and the leaf/state judgement call.
 */

/** Props for {@link CourseQaEngagementStrip}. */
export interface CourseQaEngagementStripProps {
    /**
     * Learners enrolled in the course this Q&A board belongs to. `undefined` →
     * the caller has no honest number to show yet, so the enrollment line is
     * dropped entirely rather than showing a placeholder. `0` still prints —
     * it's a real fact, not "unknown".
     */
    enrollmentCount?: number
    /** Total questions ever asked on this board. */
    totalQuestions: number
    /** Of {@link CourseQaEngagementStripProps.totalQuestions}, how many have at least one answer. */
    answeredQuestions: number
    /**
     * `true` → both lines shimmer. The flag FLOWS DOWN into the real
     * `Typography` atoms (§12c) rather than a parallel skeleton tree.
     */
    isSkeleton?: boolean
}

/**
 * The board's second line — real answered/total, or an honest admission that
 * nothing has been asked yet. Never a computed ratio from zero questions.
 */
const questionLine = (totalQuestions: number, answeredQuestions: number): string => {
    if (totalQuestions <= 0) {
        return "No questions asked yet"
    }
    return `${answeredQuestions}/${totalQuestions} questions answered`
}

/**
 * The board's honest engagement readout. See the file header for the full
 * contract.
 *
 * @param props - {@link CourseQaEngagementStripProps}
 */
const CourseQaEngagementStrip = ({
    enrollmentCount,
    totalQuestions,
    answeredQuestions,
    isSkeleton = false,
}: CourseQaEngagementStripProps) => {
    const hasEnrollment = enrollmentCount != null

    return (
        <div>
            <StackV
                gap={1}
                isSkeleton={isSkeleton}
                items={[
                    ...(isSkeleton || hasEnrollment ? [() => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={hasEnrollment ? `${enrollmentCount!.toLocaleString("vi-VN")} learners enrolled in this course` : undefined}

                        />
                    )] : []),
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : questionLine(totalQuestions, answeredQuestions)}

                        />
                    ),
                ]}
            />
        </div>
    )
}

export { CourseQaEngagementStrip }

import React from "react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { type CourseQaQuestionItem, type CourseQaQuestionScope } from "../types"

/** The block's own scope→label vocabulary (§14d.1) — never handed in pre-formatted. */
const scopeLabel = (scope: CourseQaQuestionScope): string =>
    scope.kind === "lesson" ? `Lesson: ${scope.lessonTitle}` : "General"

/** The block's own status→label vocabulary (§14d.1). */
const statusLabel = (replyCount: number, answeredByFounder?: boolean): string => {
    if (replyCount <= 0) {
        return "Not answered yet"
    }
    return answeredByFounder ? "Instructor answered" : "Answered"
}

/** Props for {@link QuestionPreviewRow}. */
interface QuestionPreviewRowProps {
    question: CourseQaQuestionItem
    currentUserId: string | null
}

/**
 * TEMPORARY GAP STAND-IN for the not-yet-built `QaQuestionThread` block — see
 * the file header's GAP note (*2). Renders the COLLAPSED look only (real data,
 * real atoms), no expand/reply behaviour: pressing does nothing, because
 * inventing a fake "open the thread" affordance here would be worse than
 * honestly having none yet.
 */
export const QuestionPreviewRow = ({ question, currentUserId }: QuestionPreviewRowProps) => {
    const isMine = currentUserId != null && currentUserId === question.author.id
    const isAnswered = question.replyCount > 0
    const askerName = isMine ? "You" : question.author.displayName

    // ONE chip for the row's classification axis (status — the thing worth scanning
    // the list for); the scope rides as plain muted text beside it instead of a
    // second chip (eslint `starci-fe/no-adjacent-chip`, *7).
    const chips: Array<ComponentTypeWithSkeleton> = [
        () => <Typography size="xs" color="muted" text={scopeLabel(question.scope)} />,
        () => (
            <Chip
                tone={isAnswered ? "success" : "default"}
                text={statusLabel(question.replyCount, question.answeredByFounder)}

            />
        ),
    ]
    if (isAnswered) {
        // no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
        // "replies" (not a universal symbol like check/locklock), and the text already carries
        // the fact on its own (same fix already applied to QaQuestionThread/QaConversationHeader).
        chips.push(() => (
            <Typography size="xs" color="muted" text={`${question.replyCount} replies`} />
        ))
    }

    const textColumnItems = [
        () => (
            <StackH
                gap={2}
                items={[
                    ...(question.isPinned ? [() => (
                        <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                    )] : []),
                    () => <Typography size="xs" weight="medium" text={askerName} />,
                    ...(question.isFounderAuthor ? [() => (
                        <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                    )] : []),
                    () => <Typography size="xs" color="muted" text={`· ${question.createdTimeAgo}`} />,
                ]}
            />
        ),
        () => <Typography size="sm" lineClamp={2} text={question.preview} />,
        () => <Cluster gap={3} items={chips} />,
    ]

    return (
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"

            items={[
                () => (
                    <div className="shrink-0">
                        <Avatar
                            src={question.author.avatarUrl}
                            name={question.author.displayName}
                            seed={question.author.id}
                            size="sm"

                        />
                    </div>
                ),
                () => <StackV gap={2} classNames={["min-w-0", "flex-1"]} items={textColumnItems} />,
                () => (
                    <span
                        aria-hidden
                        className={`size-2 shrink-0 rounded-full ${isAnswered ? "bg-success" : "bg-warning"}`}
                    />
                ),
            ]}
        />
    )
}

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"

/**
 * One placeholder row for the Loading branch — avatar + 2 text bars +
 * chip-pill row + status dot, ported verbatim from the real
 * `CourseQaSkeleton.tsx` shape (*1).
 *
 * `align="start"` on the outer row (instead of the real file's `mt-2` on the
 * dot) top-aligns all three children without a child pushing its own margin
 * (§10a — the padding gate only allows a parent's `gap`/surface `padding` to
 * own a seam).
 */
export const SkeletonQuestionRow = () => {
    return (
        <StackH identity={{ tier: "block", component: "SkeletonQuestionRow" }}
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"

            items={[
                () => (
                    <div className="shrink-0">
                        <Avatar isSkeleton size="sm" />
                    </div>
                ),
                () => (
                    <StackV
                        gap={2}
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            // asker + time line
                            () => <Typography size="xs" isSkeleton />,
                            // two-line preview
                            () => (
                                <StackV
                                    gap={2}
                                    items={[
                                        () => <Typography size="sm" isSkeleton />,
                                        () => <Typography size="sm" isSkeleton />,
                                    ]}
                                />
                            ),
                            // chip-pill row — ONE chip (status, the classification axis) + the scope
                            // as a plain shimmer bar, matching the real row's own text-inline treatment
                            // (eslint `starci-fe/no-adjacent-chip`, *7 below).
                            () => (
                                <StackH
                                    gap={3}
                                    items={[
                                        () => <Typography size="xs" isSkeleton />,
                                        () => <Chip isSkeleton />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                // status dot — no home atom (*3), same escape hatch `Pagination` uses for its own shimmer squares
                () => <HeroSkeleton className="size-2 shrink-0 rounded-full" />,
            ]}
        />
    )
}

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { LockIcon, CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { ChipGroup, type ChipGroupItem } from "@sb-components/composites/chips/ChipGroup/ChipGroup"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { RatingBar, type RatingOption } from "@sb-components/starci/blocks/learn/RatingBar/RatingBar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FlashcardStudyCard` — one card of a review run, shared by both due-review and
 * deck-review. Composes `SurfaceCard`, `MarkdownContent`, `Chip`/`ChipGroup`,
 * `Button`, and the shared `RatingBar`; only the locked-premium notice is
 * hand-rolled. One chip per meta row (`starci-fe/no-adjacent-chip`): `levelLabel`
 * takes the lone chip, `tags` ride `ChipGroup`. Three leaves: `revealed` swaps
 * question-only for answer body, and within revealed `isLocked` swaps the answer
 * for a lock notice; `levelLabel`/`tags`/`explanation` stay states. Prev/next
 * never gate on grading.
 */

/** Props for {@link FlashcardStudyCard}. */
export interface FlashcardStudyCardProps {
    /** The question, as authored markdown. */
    question: string
    /** Seniority/difficulty this card targets, e.g. "Middle" — already localized. */
    levelLabel?: string
    /** Free-form tags on the card, e.g. topic labels. Rendered as a truncating row. */
    tags?: Array<string>
    /** `true` → the answer body (or the lock notice) is shown under the question. */
    revealed: boolean
    /** Fired when the learner asks to see the answer. */
    onReveal: () => void
    /** The answer, as authored markdown. Shown only once `revealed` and not `isLocked`. */
    answer?: string
    /** Optional reasoning under the answer, as authored markdown. */
    explanation?: string
    /**
     * `true` → this card's answer is premium content the learner has not bought.
     * Only meaningful once `revealed`: the question always shows, but revealing
     * swaps in a lock notice + unlock CTA instead of the real answer.
     */
    isLocked?: boolean
    /** Fired when the learner takes the way through the lock. Required when `isLocked` can be true. */
    onUnlock?: () => void
    /** Recall grades offered once the real answer is showing. */
    ratingOptions: Array<RatingOption>
    /** Fired with the grade the learner picked. */
    onRate: (grade: number) => void
    /** `true` → a grade is in flight; `RatingBar` owns the busy affordance. */
    isRatingPending?: boolean
    /** `true` → this is the first card of the run; the previous control is disabled. */
    isFirst: boolean
    /** `true` → this is the last card of the run; the next control is disabled. */
    isLast: boolean
    /** Fired to step back a card, regardless of whether this one was graded. */
    onPrev: () => void
    /** Fired to step forward a card, regardless of whether this one was graded. */
    onNext: () => void
    /** `true` → the card draws its own mirror instead of the real content. */
    isSkeleton?: boolean
}

/**
 * One review card. See the file header for the full contract, in particular why
 * this has exactly three leaves and why prev/next never gate on grading.
 *
 * @param props - {@link FlashcardStudyCardProps}
 */
const FlashcardStudyCard = ({
    question,
    levelLabel,
    tags,
    revealed,
    onReveal,
    answer,
    explanation,
    isLocked = false,
    onUnlock,
    ratingOptions,
    onRate,
    isRatingPending = false,
    isFirst,
    isLast,
    onPrev,
    onNext,
    isSkeleton = false,
}: FlashcardStudyCardProps) => {
    const hasMeta = levelLabel != null || (tags != null && tags.length > 0)
    const tagItems: Array<ChipGroupItem> = (tags ?? []).map((tag) => ({ key: tag, text: tag }))

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ...(levelLabel != null ? [({ isSkeleton }: SkeletonProps) => <Chip isSkeleton={isSkeleton} tone="default" text={levelLabel} />] : []),
                ...(tagItems.length > 0
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <ChipGroup
                                items={tagItems}
                                isSkeleton={isSkeleton}

                            />
                        ),
                    ]
                    : []),
            ]}
        />
    ) : null

    // The one hand-rolled part of this block (see file header): no existing
    // composite draws a lock message sized for ONE card face that still has a
    // question and nav controls around it — `EmptyState` fills a whole
    // pane, which is the wrong weight here.
    const lockNotice = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            () => <LockIcon aria-hidden focusable="false" weight="bold" className="size-5 shrink-0 text-muted" />,
                            ({ isSkeleton }: SkeletonProps) => (
                                <StackV
                                    gap={1}
                                    isSkeleton={isSkeleton}
                                    items={[
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Answer locked" />,
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Upgrade to Premium to see this card's answer and explanation" />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                ({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Unlock this card" variant="primary" onPress={onUnlock} />,
            ]}
        />
    )

    const answerBody = (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={3}
                        isSkeleton={isSkeleton}
                        items={[
                            ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Answer" />,
                            () => (
                                <MarkdownContent
                                    source={answer ?? ""}
                                    measure="compact"

                                />
                            ),
                        ]}
                    />
                ),
                ...(explanation != null
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <StackV
                                gap={3}
                                isSkeleton={isSkeleton}
                                items={[
                                    ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Explanation" />,
                                    () => (
                                        <MarkdownContent
                                            source={explanation}
                                            measure="compact"

                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]
                    : []),
                // The recall grade, not the run's right/wrong — same shared block
                // and same reasoning as `QuizRecapList`'s use of it.
                ({ isSkeleton }: SkeletonProps) => (
                    <RatingBar
                        options={ratingOptions}
                        onRate={onRate}
                        ariaLabel="Choose recall level"
                        isPending={isRatingPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // Prev/next live beside reveal but never gate on it — see file header.
    const navRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="between"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretLeftIcon}
                        ariaLabel="Previous card"
                        variant="tertiary"
                        isDisabled={isFirst}
                        onPress={onPrev}

                    />
                ),
                ...(!revealed ? [({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Show answer" variant="primary" onPress={onReveal} />] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretRightIcon}
                        ariaLabel="Next card"
                        variant="tertiary"
                        isDisabled={isLast}
                        onPress={onNext}

                    />
                ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            () => metaRow,
                            () => (
                                <MarkdownContent
                                    source={question}
                                    measure="compact"

                                />
                            ),
                            ...(revealed ? [() => (isLocked ? lockNotice : answerBody)] : []),
                            () => navRow,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { FlashcardStudyCard }

import { SearchAutocomplete, type SearchAutocompleteItem } from "@sb-components/atoms/forms/SearchAutocomplete/SearchAutocomplete"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `FoundationSearchBar`: the search row — debounced-typeahead field
 * left, a live match count right, one `StackH` seam apart. See the component
 * file header for why this is a SIBLING of `FoundationCategorySearchBar`
 * (not a reach past it) and for the independent-count-loading axis that makes
 * it a distinct block rather than the same one reused.
 *
 *  ONE LEAF (§14d.2). `isSkeleton`, `isCountLoading`, an empty vs. populated
 * suggestion list, and every value `resultCount` can take (unknown / zero / N)
 * are all DATA on the same fixed structure — no node appears or disappears —
 * so they are STATES inside the single `Default` leaf, not leaves of their own.
 */

/** One autocomplete suggestion row (id + label only — the generic shape this bar needs). */
export interface FoundationSearchSuggestion {
    /** Stable id — the payload `onSelectSuggestion` fires with. */
    id: string
    /** Display label for the suggestion row. */
    label: string
}

/** Props for {@link FoundationSearchBar}. */
export interface FoundationSearchBarProps {
    /** Current text in the search field (controlled, debounced upstream by the screen). */
    query: string
    /** Fired with the new query on every keystroke. */
    onQueryChange: (query: string) => void
    /** Suggestions for the current query, best match first. */
    suggestions: Array<FoundationSearchSuggestion>
    /** Fired with the chosen suggestion's id. */
    onSelectSuggestion: (id: string) => void
    /** Placeholder for the empty field. Defaults to "Search...". */
    placeholder?: string
    /**
     * How many results the current query matched. `undefined` means the count
     * itself is not known yet (first paint, before the count read has ever
     * answered) — distinct from a real `0`, which renders.
     */
    resultCount?: number
    /**
     * `true` while the count is (re-)fetching on ITS OWN SWR read — independent
     * of `suggestions`/the field, which may already be interactive. Only the
     * count slot shimmers.
     */
    isCountLoading?: boolean
    /** Renders the field's + count's resting skeleton mirrors instead of the real controls. */
    isSkeleton?: boolean
}

/** Count wording — this block's own vocabulary, never handed in by the caller. */
const resultCountLabel = (count: number): string => (count === 0 ? "No documents yet" : `${count} documents`)

/**
 * The search row: typeahead field left, live match count right. See the file
 * header for why this is a sibling of `FoundationCategorySearchBar` rather
 * than a reach past it, and why the count's three data conditions stay one leaf.
 *
 * @param props - {@link FoundationSearchBarProps}
 */
const FoundationSearchBar = ({
    query,
    onQueryChange,
    suggestions,
    onSelectSuggestion,
    placeholder = "Search documents...",
    resultCount,
    isCountLoading = false,
    isSkeleton = false,
}: FoundationSearchBarProps) => {
    // Domain suggestion → the atom's generic item shape (no `description` line:
    // this bar's rows carry only a bare label).
    const items: Array<SearchAutocompleteItem> = suggestions.map((suggestion) => ({
        id: suggestion.id,
        label: suggestion.label,
    }))

    return (
        <div>
            <StackH
                gap={3}
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                isSkeleton={isSkeleton}

                items={[
                    () => (
                        <SearchAutocomplete
                            items={items}
                            inputValue={query}
                            onInputChange={onQueryChange}
                            onSelect={onSelectSuggestion}
                            placeholder={placeholder}
                            isSkeleton={isSkeleton}

                        />
                    ),
                    ...(isSkeleton || isCountLoading
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    color="muted"
                                    isSkeleton


                                />
                            ),
                        ]
                        : resultCount !== undefined
                            ? [
                                () => (
                                    <Typography
                                        size="sm"
                                        color="muted"
                                        tabularNums
                                        text={resultCountLabel(resultCount)}


                                    />
                                ),
                            ]
                            : []),
                ]}
            />
        </div>
    )
}

export { FoundationSearchBar }

import React from "react"
import { SpeakerHighIcon, SpeakerSlashIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `InterviewerPresence` — "someone is interviewing you": persona, live-speaking
 * cue, TTS toggle, and the question underneath. Whether the question region
 * exists is presence/absence data on the same shape — an idle and a mid-question
 * interviewer are one block with different data. `speaking` (audio) and `isAsking`
 * (text still streaming) are independent props; the identity row composes `Avatar`
 * + `Typography` directly (role, not a handle, plus a pulse ring).
 */

/** Who is interviewing — identity only, no session state. */
export interface InterviewerPresencePersona {
    /** Display name, e.g. "Ms. Mai". */
    name: string
    /** Static role/title shown under the name, e.g. "Backend Engineer". */
    role: string
    /** Uploaded avatar URL. Missing, or failing to load, falls back through `Avatar`'s own chain. */
    avatarSrc?: string
}

/** Props for {@link InterviewerPresence}. */
export interface InterviewerPresenceProps {
    /** Who is interviewing. */
    persona: InterviewerPresencePersona
    /**
     * `true` while TTS audio is actively voicing the current question. Drives
     * ONLY the pulse ring + status line — see the file header for why this is
     * independent from `isAsking`.
     */
    speaking: boolean
    /** Status text shown beside the pulse while `speaking` is true, e.g. "Reading the question". Localized by the caller. */
    speakingLabel: string
    /**
     * `true` → this session offers a TTS toggle at all. Omitted/`false` → the
     * toggle is not drawn: a control that cannot do anything is not a control
     * (same reasoning as `ContentModeNav`'s language switcher below two languages).
     */
    ttsSupported?: boolean
    /** Current TTS on/off state. Only read while `ttsSupported` is true. */
    ttsEnabled?: boolean
    /** Fired when the learner presses the toggle. Only read while `ttsSupported` is true. */
    onToggleTts?: () => void
    /** Toggle's accessible label for the moment TTS is ON (pressing it mutes). */
    muteLabel: string
    /** Toggle's accessible label for the moment TTS is OFF (pressing it unmutes). */
    unmuteLabel: string
    /**
     * The current question, as authored/streamed markdown. Absent or blank →
     * no question region at all — the interviewer is between questions.
     */
    questionMarkdown?: string
    /**
     * `true` while this question's TEXT is still arriving. Adds a typing cue
     * under the question; has no effect once `questionMarkdown` is blank —
     * there is nothing yet to attach the cue to.
     */
    isAsking?: boolean
}

/**
 * The interviewer's presence header: identity, live-speaking cue, TTS toggle,
 * and the question underneath. See the file header for the full contract.
 *
 * @param props - {@link InterviewerPresenceProps}
 */
const InterviewerPresence = ({
    persona,
    speaking,
    speakingLabel,
    ttsSupported = false,
    ttsEnabled,
    onToggleTts,
    muteLabel,
    unmuteLabel,
    questionMarkdown,
    isAsking = false,
}: InterviewerPresenceProps) => {
    const hasQuestion = Boolean(questionMarkdown && questionMarkdown.trim().length > 0)
    // A control that cannot do anything is not drawn — mirrors ContentModeNav's
    // language switcher, which only appears once it has two real options.
    const canToggleTts = ttsSupported && ttsEnabled != null && onToggleTts != null
    const TtsIcon = ttsEnabled ? SpeakerHighIcon : SpeakerSlashIcon
    // The icon shows the CURRENT state; the label names the ACTION the press performs.
    const ttsAriaLabel = ttsEnabled ? muteLabel : unmuteLabel

    // Relative wrapper only to anchor the decorative pulse ring — not a
    // spacing seam, so it stays a plain span rather than a frame.
    const avatarWithPulse = (
        <span className="relative inline-flex shrink-0">
            {speaking ? (
                <span
                    aria-hidden
                    className="absolute -inset-1 animate-ping rounded-full ring-2 ring-accent"
                />
            ) : null}
            <Avatar
                name={persona.name}
                src={persona.avatarSrc}
                seed={persona.name}
                size="lg"

            />
        </span>
    )

    const speakingStatus = speaking ? (
        <StackH
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"

            items={[
                () => <span aria-hidden className="size-1.5 animate-pulse rounded-full bg-accent" />,
                () => (
                    <Typography
                        text={speakingLabel}
                        size="sm"
                        color="accent"
                        weight="medium"

                    />
                ),
            ]}
        />
    ) : null

    const nameAndRole = (
        <StackV
            gap={1}
            principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."

            items={[
                () => (
                    <Typography
                        text={persona.name}
                        weight="medium"

                    />
                ),
                () => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"

                        items={[
                            () => (
                                <Typography
                                    text={persona.role}
                                    size="sm"
                                    color="muted"

                                />
                            ),
                            () => speakingStatus,
                        ]}
                    />
                ),
            ]}
        />
    )

    const identity = (
        <StackH
            gap={3}
            principle="identity"
            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
            align="center"

            items={[
                () => avatarWithPulse,
                () => nameAndRole,
            ]}
        />
    )

    const toggleButton = canToggleTts ? (
        <Button
            isIconOnly
            variant="ghost"
            prefixIcon={TtsIcon}
            ariaLabel={ttsAriaLabel}
            onPress={onToggleTts}

        />
    ) : null

    const headerRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center"
            justify="between"

            items={[
                () => identity,
                () => toggleButton,
            ]}
        />
    )

    const typingDots = isAsking ? (
        <StackH
            gap={2}
            principle="separator-dot"
            explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
            align="center"

            items={[
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted" />,
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted [animation-delay:150ms]" />,
                () => <span aria-hidden className="size-1.5 animate-bounce rounded-full bg-muted [animation-delay:300ms]" />,
            ]}
        />
    ) : null

    const questionRegion = hasQuestion ? (
        <StackV
            gap={2}

            items={[
                () => (
                    <MarkdownContent
                        source={questionMarkdown as string}
                        measure="reading"


                    />
                ),
                () => typingDots,
            ]}
        />
    ) : null

    return (
        <div>
            <StackV
                gap={3}

                items={[
                    () => headerRow,
                    () => questionRegion,
                ]}
            />
        </div>
    )
}

export { InterviewerPresence }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { CheckCircleIcon, CircleIcon, LockIcon, PlayCircleIcon } from "@phosphor-icons/react"
import { SurfaceCardList } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@sb-components/starci/blocks/learn/VariantChip/VariantChip"
/**
 * `KeepGoingPath` — the continue-learning path for the current chapter, answering
 * "where am I + what's next". Deliberately does not redraw the full module tree
 * (that lives in the left rail). The block owns the shape — state icon
 * (play/check/circle), difficulty chip, lock — while the caller supplies only data.
 * Every variant shares one `SurfaceCardList` → rows tree, differing only in content.
 */
/** Learning state of a content item in the path. */
export type KeepGoingContentState = "done" | "active" | "todo"
/** A content item in the path — plain DATA, the block builds the shape itself. */
export interface KeepGoingContent {
    /** Stable React key. */
    id: string
    /** Content title. */
    title: string
    /** Reading time (minutes) — the block assembles it into the subtitle line. */
    minutes: number
    /** Done / in progress / not started — decides the leading icon. */
    state: KeepGoingContentState
    /** Difficulty — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Content belongs to a paid tier → shows the lock mark. */
    locked?: boolean
    /** Row press handler. */
    onPress?: () => void
}
/**
 * Leading icon per state — the block owns this table, the caller doesn't pick.
 * Goes through `leading` (a node) rather than `leadingIcon`, because each state
 * carries its OWN COLOR while `leadingIcon` forces a shared `text-muted`.
 *
 * ALL THREE STATES SHARE ONE ROUND SHAPE: the in-progress
 * state uses `PlayCircleIcon` (a play mark INSIDE a circle) rather than a bare triangle
 * (`PlayIcon`) — its two siblings `CheckCircleIcon`/`CircleIcon` are both circles, so one
 * shape breaking the mould breaks the row's reading rhythm.
 *
 * `size-5` — the row's leading icon size (heading icon = 5;
 * the icon inside the chip follows the font instead).
 */
/** The leading mark one content state resolves to: which glyph, and how it is coloured. */
interface ContentLeadingStyle {
    /** Phosphor glyph component for this state. */
    Icon: typeof CircleIcon
    /** Size + colour classes; every state stays on one round shape (see the note above). */
    className: string
}
const CONTENT_LEADING: Record<KeepGoingContentState, ContentLeadingStyle> = {
    active: { Icon: PlayCircleIcon, className: "size-5 text-accent-soft-foreground" },
    done: { Icon: CheckCircleIcon, className: "size-5 text-success-soft-foreground" },
    todo: { Icon: CircleIcon, className: "size-5 text-foreground" },
}
/**
 * A LOCKED content item → the lock icon **REPLACES** the state icon at the head of
 * the row instead of hanging a second one on the tail.
 *
 * COLOR: `warning` — NOT muted. A muted lock turns
 * invisible, and this isn't decoration: it's a SALES DOOR, it has to be seen. Uses
 * the `-soft-foreground` step to match its siblings (accent/success), not a bold
 * `text-warning`.
 *
 * Why it sits at the HEAD of the row: a standard list row already has leading ·
 * title · subtitle · meta; bolting a second icon onto the tail just creates a spot
 * nobody reads. And semantically: for a not-yet-unlocked item, "read / reading /
 * unread" is meaningless — **the lock IS its state**.
 */
const LOCKED_LEADING = { Icon: LockIcon, className: "size-5 text-warning-soft-foreground" }
/**
 * The MODULE this path belongs to.
 *
 * A `string` prop cannot be checked: nothing stops a caller sending `"chapter 2-"` or a
 * completely different sentence. Two named fields make the wrong shape UNTYPEABLE.
 *
 * Declared as a NAMED, EXPORTED interface rather than inline `{ index: number; name:
 * string }`: an inline shape has no name to
 * import, so a caller building this object has nothing to type it against and every
 * call-site re-describes it by hand.
 */
export interface ModuleLike {
    /** 1-based position of the module inside the course. */
    index: number
    /** Module name WITHOUT any prefix — the block adds "Chapter"/"Continue" itself. */
    name: string
}
/** Props for {@link KeepGoingPath}. */
export interface KeepGoingPathBaseProps {
    /** The current module as an ENTITY — never a pre-baked string. See {@link ModuleLike}. */
    module: ModuleLike
    /** The content items in the continue-learning path. */
    contents: Array<KeepGoingContent>
    /**
     * `true` → mirror shimmer INSTEAD OF waiting on `contents`. The flag FLOWS
     * DOWN into `SurfaceCardList` (keeps the box/row/divider, only the text turns
     * to shimmer) and into `VariantChipDifficulty` — both the atom and the frame
     * already own their own `isSkeleton`.
     *
     * Empty while loading (`contents.length === 0`) → guesses **3** rows, matching
     * this pass's convention for repeating lists.
     *
     * NOTE: the leading icon (play/check/circle/lock) is chosen DIRECTLY by the block
     * itself from the `CONTENT_LEADING`/`LOCKED_LEADING` table — it doesn't go
     * through any atom — so this is exactly the §12c case that allows hand-rolling
     * ONE shimmer dot in place of the icon, instead of branching off to build a
     * whole separate row.
     */
    isSkeleton?: boolean
}
/** Placeholder DATA for the 3 guessed rows when `contents` is empty while loading (§12c). */
const SKELETON_ROWS: Array<KeepGoingContent> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    minutes: 0,
    state: "todo",
    difficulty: "beginner",
}))
/**
 * Continue-learning path — module heading + content list, sharing its layout with
 * `LearnNudges`.
 *
 * @param props - {@link KeepGoingPathBaseProps}
 */
const KeepGoingPathBase = ({
    module,
    contents,
    isSkeleton = false,
}: KeepGoingPathBaseProps) => {
    // Empty while loading (no real contents yet) → guess 3 rows, keeping the right
    // shape for when real data arrives (§8). Once real `contents` exist, keep the
    // EXACT row count already there.
    const rows = isSkeleton && contents.length === 0 ? SKELETON_ROWS : contents
    return (
        <SurfaceCardList
            // The heading sentence is assembled by the BLOCK — the caller only hands over the module name.
            // EVERY word of the heading is decided HERE — "Continue", "Chapter", the `·`.
            // The caller only supplies the number and the name.
            label={`Continue · Chapter ${module.index} · ${module.name}`}

            isSkeleton={isSkeleton}
            items={rows.map((content) => {
                // A lock REPLACES the state icon, it isn't added on top at the row's tail.
                const { Icon, className } = content.locked
                    ? LOCKED_LEADING
                    : CONTENT_LEADING[content.state]
                return {
                    key: content.id,
                    leading: isSkeleton ? (
                        // The icon is chosen DIRECTLY by the block itself (no atom in between) —
                        // hand-roll a single shimmer dot in place of the state/lock icon.
                        () => <HeroSkeleton className="size-5 shrink-0 rounded-full" />
                    ) : (
                        () => (
                            <Icon
                                aria-label={content.locked ? "Paid content" : undefined}
                                aria-hidden={content.locked ? undefined : true}
                                focusable="false"
                                className={className}
                            />
                        )
                    ),
                    title: content.title,
                    subtitle: `${content.minutes} min read`,
                    onPress: content.onPress,
                    // Meta now holds EXACTLY ONE thing: difficulty. The shape is owned by
                    // DESIGN — the block doesn't reshape the chip (§14d.1). The flag flows
                    // straight down into the `VariantChipDifficulty` atom.
                    meta: () => (
                        <VariantChipDifficulty
                            difficulty={content.difficulty}
                            isSkeleton={isSkeleton}

                        />
                    ),
                }
            })}
        />
    )
