import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { CheckIcon, CircleIcon, LockIcon, PlayIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@sb-components/starci/blocks/learn/VariantChip/VariantChip"

/**
 * `ModuleLessonList` — the full, ordered lesson table of contents for one module —
 * every lesson, not just what's next. Sibling of `KeepGoingPath` (which trims to
 * the continue-learning queue and owns a heading); this block takes no heading of
 * its own. The block owns the per-row status icon (`resume`/`read`/`unread`), the
 * "N min read · M challenges" subtitle, and whether a difficulty chip and premium
 * lock ride on the trailing side. Row-level differences are states of one
 * `SurfaceCardList` tree; `isSkeleton` is its own leaf.
 */

/** Where this lesson sits in the reader's progress through the module. */
type LessonStatus = "resume" | "read" | "unread"

/** One lesson row — plain data; the block assembles the wording and the icon. */
export interface ModuleLessonListLesson {
    /** Stable id — also what `onSelectLesson`/`resumeLessonId` key off. */
    id: string
    /** Lesson title. */
    title: string
    /** Reading time in minutes — the block folds this into the subtitle itself. */
    minutesRead: number
    /** Practice-challenge count for this lesson — folded into the same subtitle. */
    challengeCount: number
    /** Already finished at least once. */
    isRead: boolean
    /** Behind the paid tier — shows the trailing lock marker. */
    isPremium: boolean
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. Omit → no chip. */
    difficulty?: Difficulty
}

/** Props for {@link ModuleLessonList}. */
export interface ModuleLessonListProps {
    /** Every lesson in the module, in reading order. */
    lessons: Array<ModuleLessonListLesson>
    /** The lesson to mark "resume" — wins over `isRead` for the leading icon (see file header). */
    resumeLessonId?: string
    /** Fired with the lesson id on ANY row press, premium or not (see the  note above). */
    onSelectLesson: (id: string) => void
    /**
     * `true` → the list draws its own row mirror. `lessons` empty while loading
     * (§12c) → guesses 3 rows, the SSOT convention this composite's siblings
     * (`KeepGoingPath`, `LearnNudges`) already use.
     */
    isSkeleton?: boolean
}

/** Resolves the leading-icon state: `resumeLessonId` wins over `isRead` (see file header). */
const lessonStatus = (lesson: ModuleLessonListLesson, resumeLessonId?: string): LessonStatus => {
    if (resumeLessonId != null && lesson.id === resumeLessonId) {
        return "resume"
    }
    return lesson.isRead ? "read" : "unread"
}

/** The leading mark one lesson status resolves to: which glyph, and how it is coloured. */
interface LessonLeadingStyle {
    /** Phosphor glyph component for this status. */
    Icon: typeof CircleIcon
    /** Size + colour classes. */
    className: string
}

/** Leading glyph + colour per status — the block owns this table, the caller never picks an icon. */
const STATUS_LEADING: Record<LessonStatus, LessonLeadingStyle> = {
    resume: { Icon: PlayIcon, className: "size-5 text-accent-soft-foreground" },
    read: { Icon: CheckIcon, className: "size-5 text-success-soft-foreground" },
    unread: { Icon: CircleIcon, className: "size-5 text-foreground" },
}

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler. */
const SKELETON_LESSONS: Array<ModuleLessonListLesson> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    minutesRead: 0,
    challengeCount: 0,
    isRead: false,
    isPremium: false,
    difficulty: "beginner",
}))

/**
 * The module's full lesson table of contents. See the file header for the full
 * contract and the two judgement calls that set it apart from `KeepGoingPath`.
 *
 * @param props - {@link ModuleLessonListProps}
 */
const ModuleLessonList = ({
    lessons,
    resumeLessonId,
    onSelectLesson,
    isSkeleton = false,
}: ModuleLessonListProps) => {
    // Empty while loading (no real lessons yet) → guess 3 rows, keeping the right
    // shape for when real data arrives (§8). Once real `lessons` exist, keep the
    // EXACT row count already there — the placeholder set never mixes with real rows.
    const usingPlaceholders = isSkeleton && lessons.length === 0
    const source = usingPlaceholders ? SKELETON_LESSONS : lessons

    const rows: Array<SurfaceCardListItem> = source.map((lesson) => {
        const { Icon, className } = STATUS_LEADING[lessonStatus(lesson, resumeLessonId)]
        return {
            key: lesson.id,
            leading: () => (isSkeleton ? (
                // The status icon is chosen DIRECTLY by the block from `STATUS_LEADING`,
                // never through an atom in between — hand-roll a single shimmer dot in
                // its place instead of branching off to build a whole separate row (§12c).
                <HeroSkeleton className="size-5 shrink-0 rounded-full" />
            ) : (
                <Icon aria-hidden focusable="false" className={className} />
            )),
            title: lesson.title,
            // The subtitle sentence is assembled HERE — the caller hands over two
            // numbers, never a pre-formatted string (§14d.1).
            subtitle: `${lesson.minutesRead} min read · ${lesson.challengeCount} challenges`,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectLesson(lesson.id),
            // Difficulty is DESIGN's shape (`VariantChipDifficulty`, §14d.1) — the block
            // doesn't reshape the chip, only decides whether one is offered at all.
            meta: lesson.difficulty != null ? () => (
                <VariantChipDifficulty
                    difficulty={lesson.difficulty!}
                    isSkeleton={isSkeleton}

                />
            ) : undefined,
            // A quiet trailing marker, riding NEXT TO the chip rather than replacing the
            // leading icon (see the * judgement call above).
            trailingIcon: lesson.isPremium ? LockIcon : undefined,
        }
    })

    return (
        <SurfaceCardList

            isSkeleton={isSkeleton}
            items={rows}
        />
    )
}

export { ModuleLessonList }

import React from "react"
import { StatRibbon, type StatRibbonItem } from "@sb-components/composites/stats/StatRibbon/StatRibbon"

/**
 * `PlaygroundDeviceSnapshot` — "Your machine": the paired agent's raw hardware
 * report turned into the same 4-cell `StatRibbon` the Lab route shows, so setup and
 * the live lab agree about what the machine can run. Reuses `StatRibbon`; the block
 * owns the domain judgement — bytes → GB rounding, the `win32`/`darwin`/`linux` →
 * "Windows"/"macOS"/"Linux" table, and the three sentences a GPU cell can say
 * depending on which of `gpu`/`vramTotalMb`/`vramFreeMb` came back. Every
 * `deviceInfo` combination and `isSkeleton` are states of the 4-cell shape.
 */

/**
 * The paired agent's hardware/OS snapshot, exactly as it arrives over the
 * `device:info` socket message — ported faithfully from
 * `PlaygroundDeviceInfo` in
 * `src/components/features/learn/Playground/PlaygroundPrepare/index.tsx`
 * (itself mirroring `PlaygroundByomDeviceInfoSocketIoMessage`).
 */
export interface PlaygroundDeviceInfo {
    /** `win32` | `linux` | `darwin`. */
    platform: string
    /** CPU architecture (`x64`, `arm64`, …). */
    arch: string
    /** Machine hostname. */
    hostname: string
    /** CPU model string. */
    cpuModel: string
    /** Logical CPU core count. */
    cpuCores: number
    /** Total RAM in bytes. */
    totalMemBytes: number
    /** Free RAM in bytes (at snapshot time). */
    freeMemBytes: number
    /** First discrete GPU name, or `null` if it couldn't be read. */
    gpu: string | null
    /** Free GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramFreeMb?: number
    /** Total GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramTotalMb?: number
}

/** Bytes → whole GB, the unit the ribbon reads in. */
const gbOf = (bytes: number): number => Math.round(bytes / 1e9)

/**
 * Node's `process.platform` id → the name a learner recognises.
 * @param platform - `win32` / `darwin` / `linux` (or anything else, passed through).
 */
const platformLabel = (platform: string): string =>
    platform === "win32"
        ? "Windows"
        : platform === "darwin"
            ? "macOS"
            : platform === "linux" ? "Linux" : platform

/**
 * The GPU cell's detail line: total + free VRAM when the agent could read an
 * NVIDIA card, an empty second line when a GPU exists but VRAM couldn't be
 * read, or an explicit "unknown" when no GPU was detected at all — three
 * distinct facts, not one string with a blank filled in.
 */
const vramDetail = (gpu: string | null, vramTotalMb?: number, vramFreeMb?: number): string =>
    vramTotalMb
        ? `${Math.round(vramTotalMb / 1024)} GB VRAM${vramFreeMb != null ? ` · ${vramFreeMb} MB free` : ""}`
        : gpu ? "" : "couldn't read"

/**
 * One ribbon cell's label: the fixed category word, plus the computed detail
 * when there is one — `StatRibbonItem.label` is a plain `string` (the ribbon
 * renders it itself through `Typography`), so caption and detail join into a
 * single line instead of the old two-line `<span>`.
 */
const deviceStatLabel = (caption: string, detail: string): string =>
    detail ? `${caption} · ${detail}` : caption

/** Props for {@link PlaygroundDeviceSnapshot}. */
export interface PlaygroundDeviceSnapshotProps {
    /** The paired machine's hardware/OS snapshot to render as a stat ribbon. */
    deviceInfo: PlaygroundDeviceInfo
    /** `true` → every cell's value/detail line swaps to its own shimmer. */
    isSkeleton?: boolean
}

/**
 * "Your machine": the paired agent's hardware report as a 4-cell stat ribbon
 * (OS · CPU · RAM · GPU). See the file header for the unit math, the
 * platform-name table, and why this composes `StatRibbon` instead of a new
 * shape.
 *
 * @param props - {@link PlaygroundDeviceSnapshotProps}
 */
const PlaygroundDeviceSnapshot = ({
    deviceInfo,
    isSkeleton = false,
}: PlaygroundDeviceSnapshotProps) => {
    const items: ReadonlyArray<StatRibbonItem> = [
        {
            key: "os",
            value: platformLabel(deviceInfo.platform),
            label: deviceStatLabel("Operating system", `${deviceInfo.arch} · ${deviceInfo.hostname}`),
        },
        {
            key: "cpu",
            value: `${deviceInfo.cpuCores} cores`,
            label: deviceStatLabel("CPU", deviceInfo.cpuModel),
        },
        {
            key: "ram",
            value: `${gbOf(deviceInfo.totalMemBytes)} GB`,
            label: deviceStatLabel("RAM", `${gbOf(deviceInfo.freeMemBytes)} GB free`),
        },
        {
            key: "gpu",
            value: deviceInfo.gpu ?? "—",
            label: deviceStatLabel("GPU", vramDetail(deviceInfo.gpu, deviceInfo.vramTotalMb, deviceInfo.vramFreeMb)),
        },
    ]

    return (
        <div>
            <StatRibbon
                valueType="body"
                isSkeleton={isSkeleton}
                items={items}

            />
        </div>
    )
}

export { PlaygroundDeviceSnapshot }

