import React from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { InputTextarea } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizQuestion` — one question, the learner's answer, and the verdict. The answer
 * field turns read-only after grading rather than emptying (the value of a drill is
 * comparing what you said with what was expected). The expected answer appears only
 * after grading. The verdict is a chip; the reasoning rides as a document below it.
 * No score number — the running total lives in `WorkSessionHeader`.
 */

/** How the answer was judged. */
export type QuizVerdict = "correct" | "incorrect"

/** Props for {@link QuizQuestion}. */
export interface QuizQuestionProps {
    /** The question, as authored markdown. */
    question: string
    /** Seniority this question aims at, e.g. "Middle" — already localized. */
    levelLabel?: string
    /** What the learner has typed. */
    answer: string
    /** Fired as the learner types. Ignored once graded. */
    onAnswerChange: (value: string) => void
    /** Fired when the learner submits for grading. */
    onSubmit: () => void
    /** Set → the answer has been judged; the field locks and the verdict shows. */
    verdict?: QuizVerdict
    /** The expected answer, as markdown. Shown ONLY after grading. */
    expectedAnswer?: string
    /** Why the answer was judged that way, as markdown. Shown only after grading. */
    explanation?: string
    /** Label of the submit control, localized by the caller. */
    submitLabel: string
    /** Label of the move-on control shown after grading. */
    nextLabel: string
    /** Fired when the learner moves to the next question. */
    onNext: () => void
    /** `true` → grading is in flight; the submit control owns the busy affordance. */
    isPending?: boolean
    /** `true` → the card mirrors itself while the question is drawn. */
    isSkeleton?: boolean
}

/**
 * One drill question. See the file header for the full contract.
 *
 * @param props - {@link QuizQuestionProps}
 */
const QuizQuestion = ({
    question,
    levelLabel,
    answer,
    onAnswerChange,
    onSubmit,
    verdict,
    expectedAnswer,
    explanation,
    submitLabel,
    nextLabel,
    onNext,
    isPending = false,
    isSkeleton = false,
}: QuizQuestionProps) => {
    const isGraded = verdict != null

    const levelRow = levelLabel != null ? (
        <StackH
            gap={3}
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            align="center"
            isSkeleton={isSkeleton}
            items={[() => <Chip tone="default" text={levelLabel} isSkeleton={isSkeleton} />]}
        />
    ) : null

    const expectedAnswerBlock = expectedAnswer != null ? (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Expected answer" />,
                () => (
                    <MarkdownContent
                        source={expectedAnswer}
                        measure="compact"

                    />
                ),
            ]}
        />
    ) : null

    const gradedDetails = isGraded ? (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            // One chip for the classifying axis. The reasoning below is an
                            // ordinary document — two loud signals and the learner reads the
                            // verdict twice.
                            () => (
                                <Chip
                                    tone={verdict === "correct" ? "success" : "danger"}
                                    icon={verdict === "correct" ? CheckCircleIcon : XCircleIcon}
                                    text={verdict === "correct" ? "Correct" : "Not quite"}
                                    isSkeleton={isSkeleton}
                                />
                            ),
                        ]}
                    />
                ),
                () => expectedAnswerBlock,
                ...(explanation != null ? [() => (
                    <MarkdownContent
                        source={explanation}
                        measure="compact"

                    />
                )] : []),
            ]}
        />
    ) : null

    const actionRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                () =>
                    isGraded ? (
                        <Button label={nextLabel} variant="primary" onPress={onNext} />
                    ) : (
                        <Button
                            label={submitLabel}
                            variant="primary"
                            onPress={onSubmit}
                            isDisabled={answer.trim().length === 0}
                            isPending={isPending}

                        />
                    ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        items={[
                            ...(levelRow != null ? [() => levelRow] : []),
                            () => (
                                <MarkdownContent
                                    source={question}
                                    measure="reading"

                                />
                            ),
                            // Read-only rather than emptied: the whole value of a drill is comparing
                            // what you SAID with what was expected, and clearing the field takes that
                            // comparison away exactly when it becomes useful.
                            () => (
                                <InputTextarea
                                    value={answer}
                                    onValueChange={onAnswerChange}
                                    placeholder="Answer as if you're speaking to the interviewer"
                                    ariaLabel="Answer"
                                    rows={4}
                                    isDisabled={isGraded}

                                />
                            ),
                            ...(gradedDetails != null ? [() => gradedDetails] : []),
                            () => actionRow,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { QuizQuestion }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { InputText } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then start
 * it. The block owns the domain wording and the lengths behind it: the learner
 * picks "quick" or "deep" and the block turns that into 5 or 10 cards, saying so on
 * the button. A run already in progress takes priority — the resume strip leads the
 * card above the form. A failed draw is reported next to the button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            ...(resumable != null ? [() => (
                                // A learner who left mid-run almost always means to come back. Making
                                // them scroll past a start button to find their own session is how one
                                // run gets abandoned twice.
                                <Callout
                                    title={resumable.name}
                                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                                    actionLabel="Continue"
                                    onAction={resumable.onResume}

                                />
                            )] : []),
                            () => nameField,
                            () => lengthField,
                            () => levelField,
                            () => actionField,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { QuizSetup }

import React from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup, type ButtonRadioGroupItem } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `SubmissionAttemptSelector` — which graded attempt the reader is looking at: a
 * flex-wrap row of attempt buttons (verdict + "Attempt N" + score) plus an optional
 * "+N" trigger for the rest of the history. The select chrome is `ButtonRadioGroup`
 * and each button's content is a `Chip`; the block turns `{ attemptNumber, score,
 * isPassing }` into that composition, and the "+N" trigger uses the group's own
 * `trailing` slot. Pressing "+N" only fires `onOverflowPress` — what it opens is a
 * screen decision. Loading, empty, error, few, and many attempts are all states of
 * the one chip strip.
 */

/** One graded attempt the reader can switch to. */
export interface SubmissionAttempt {
    /** Stable id — the value reported to {@link SubmissionAttemptSelectorProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the block turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet (or ungraded by design); shown without a score. */
    score: number | null
    /** Drives the verdict glyph + `Chip` tone — pass (`success`) or fail (`danger`). */
    isPassing: boolean
}

/** Props for {@link SubmissionAttemptSelector}. */
export interface SubmissionAttemptSelectorProps {
    /** The attempts offered, in display order. */
    attempts: Array<SubmissionAttempt>
    /** The attempt currently being viewed. Unset → none selected yet. */
    selectedId?: string
    /** Fired with the id of the attempt the reader picked. */
    onSelect: (id: string) => void
    /** Accessible name for the row, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
    /** How many MORE attempts exist beyond this row — set (and > 0) → the "+N" trigger shows. */
    overflowCount?: number
    /** Label for the "+N" trigger. Defaults to `+{overflowCount}` when omitted. */
    overflowLabel?: string
    /**
     * Fired when the reader presses "+N". What that opens is the CALLER's call
     * (Rule 7) — a history drawer, a modal, a route change — this block only
     * reports the press.
     */
    onOverflowPress?: () => void
    /** `true` → this row's own fetch is in flight; the strip shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the row falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state message. Defaults to a standard "no attempts yet" line. */
    emptyLabel?: string
    /** Truthy → the row falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No attempts to choose from yet"
const ERROR_TITLE = "Couldn't load the attempt list"

/** No attempt id is ever the empty string, so `""` safely reads as "none selected". */
const NONE_SELECTED = ""

/** How many skeleton pills mirror the strip while `attempts` hasn't landed yet. */
const SKELETON_ITEM_COUNT = 3

/** Turns one attempt into its `Chip` — the verdict glyph, "Attempt N", and its score. */
const attemptChip = (attempt: SubmissionAttempt) => (
    <Chip
        icon={attempt.isPassing ? CheckCircleIcon : XCircleIcon}
        tone={attempt.isPassing ? "success" : "danger"}
        text={attempt.score != null ? `Attempt ${attempt.attemptNumber} · ${attempt.score}` : `Attempt ${attempt.attemptNumber}`}

    />
)

/** Mirrors the real strip's footprint while attempts are loading — pill-for-pill, no data. */
const AttemptRowSkeleton = () => (
    <Cluster
        gap={3}

        items={Array.from({ length: SKELETON_ITEM_COUNT }, () => () => <Button isSkeleton size="sm" />)}
    />
)

/**
 * The graded-attempt row. See the file header for what it owns (verdict+label
 * wording, the few-vs-many decision) and what it deliberately does not (what
 * "+N" opens).
 *
 * @param props - {@link SubmissionAttemptSelectorProps}
 */
const SubmissionAttemptSelector = ({
    attempts,
    selectedId,
    onSelect,
    ariaLabel,
    overflowCount,
    overflowLabel,
    onOverflowPress,
    isLoading = false,
    isEmpty = false,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionAttemptSelectorProps) => {
    const hasOverflow = (overflowCount ?? 0) > 0

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyLabel ?? EMPTY_LABEL_DEFAULT,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const items: Array<ButtonRadioGroupItem<string>> = attempts.map((attempt) => ({
        value: attempt.id,
        content: attemptChip(attempt),
    }))

    return (
        <div>
            <AsyncContent
                // A parent-forced skeleton and this row's own in-flight fetch share the
                // one loading branch `AsyncContent` exposes (see file header).
                isLoading={isLoading || isSkeleton}
                skeleton={() => <AttemptRowSkeleton />}
                isEmpty={isEmpty}
                emptyContent={emptyContent}
                error={error}
                errorContent={errorContent}

                content={() => (
                    <ButtonRadioGroup
                        ariaLabel={ariaLabel}
                        value={selectedId ?? NONE_SELECTED}
                        onChange={onSelect}
                        items={items}

                        trailing={
                            hasOverflow ? (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    label={overflowLabel ?? `+${overflowCount}`}
                                    onPress={onOverflowPress}

                                />
                            ) : undefined
                        }
                    />
                )}
            />
        </div>
    )
}

export { SubmissionAttemptSelector }

import React from "react"
import { LinkBack } from "@sb-components/atoms/navigation/Link/Link"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"

/**
 * `SubmissionResultHeader` — the identity band of a graded-result page: a way back
 * to the challenge, plus the requirement's title and description. Sibling of
 * `ContentHeader`, but a result page has left the material — no read-state chip,
 * minutes, or outcomes card, just "where am I, what is this, how do I leave". The
 * breadcrumb slot holds a `LinkBack` composed from `backLabel` + `onBack`. One
 * shape: `isSkeleton` is a state, since only the data changes.
 */

/** Props for {@link SubmissionResultHeader}. */
export interface SubmissionResultHeaderProps {
    /** Back-link label, localized by the caller, e.g. "Back to the solution". */
    backLabel: string
    /** Fired when the learner leaves the result page for the challenge solve page. */
    onBack: () => void
    /** The graded requirement's title. */
    title: string
    /** The requirement's own description/prompt. Omitted → the header ends at the title. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms (or their skeleton mirror when the atom has none
     * of its own) rather than building a parallel skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Identity band of a graded-result page. See the file header for the full
 * contract and why the breadcrumb slot holds a back-link instead of a trail.
 *
 * @param props - {@link SubmissionResultHeaderProps}
 */
const SubmissionResultHeader = ({
    backLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: SubmissionResultHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton ? (
                        <Typography size="sm" isSkeleton />
                    ) : (
                        <LinkBack label={backLabel} onPress={onBack} />
                    )
                }
                title={title}
                description={description}
            />
        </div>
    )
}

export { SubmissionResultHeader }

import React from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `SubmissionScoreCard` — the headline signal after the attempt selector on a
 * graded-result page: a tinted pass/fail score hero, a verdict chip + "needs N more
 * points" sub-line, optional short feedback, an optional submission link, and an
 * optional model-byline row (who graded it, its tier, when). Sibling of
 * `SubmissionResultHeader` — the header answers "what was I graded on", this card
 * answers "how did it go". Pass/fail drives both the hero number's color and the
 * verdict chip's tone together. Every optional part and `isSkeleton` are states of
 * one shape.
 */

/** Cost/quality tier of the model that produced the grade. */
export type AiModelCategory = "low" | "medium" | "high"

/** Category → `EnumChip` presentation across the three capability tiers. */
export const MODEL_CATEGORY_MAP: Record<AiModelCategory, EnumChipEntry> = {
    low: { color: "default", label: "Low" },
    medium: { color: "accent", label: "Medium" },
    high: { color: "danger", label: "High" },
}

/** Props for {@link SubmissionScoreCard}. */
export interface SubmissionScoreCardProps {
    /** Points earned on this attempt. */
    score: number
    /** Points the attempt was scored out of. Omit when the scale isn't fixed (e.g. a raw points total). */
    maxScore?: number
    /** Whether this score cleared the pass bar — drives the tinting on the hero number and the verdict chip. */
    isPassing: boolean
    /** The pass bar itself, in points. Only used to compute the "need N more points" sub-line while failing. */
    passScore?: number
    /** A short line of grader feedback, plain text. */
    shortFeedback?: string
    /** Link to the full submission. Omit to hide the link entirely. */
    submissionUrl?: string
    /** Link text for {@link submissionUrl}. Defaults to "View submission". */
    submissionLabel?: string
    /** The model that produced this grade. Omit when no model was recorded — the whole byline row then drops. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}, shown as a trailing chip. */
    modelCategory?: AiModelCategory
    /** Overrides the byline's leading word. Defaults to "Graded by". */
    gradedByLabel?: string
    /** Relative time since grading, already localized (e.g. "5 minutes ago"). */
    timeAgo?: string
    /** Section label above the card, e.g. "Grading result". */
    label: string
    /** `true` → every part this block renders itself mirrors as shimmer. */
    isSkeleton?: boolean
}

/**
 * The score signal card. See the file header for the tinting/wording/byline
 * rules this block owns.
 *
 * @param props - {@link SubmissionScoreCardProps}
 */
const SubmissionScoreCard = ({
    score,
    maxScore,
    isPassing,
    passScore,
    shortFeedback,
    submissionUrl,
    submissionLabel,
    gradedByModel,
    modelCategory,
    gradedByLabel,
    timeAgo,
    label,
    isSkeleton = false,
}: SubmissionScoreCardProps) => {
    // One tone drives BOTH the hero number and the verdict chip — a passing and a
    // failing score must never read as two independent signals.
    const verdictTone: "success" | "danger" = isPassing ? "success" : "danger"
    // Only meaningful while failing: a passing attempt has already cleared the bar,
    // so there is nothing left to need.
    const pointsNeeded = !isPassing && passScore != null ? Math.max(passScore - score, 0) : null

    const modelByline = gradedByModel != null ? (
        <StackH
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            at="sm"
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <InlineIconLabel
                        icon={SparkleIcon}
                        tone="default"
                        size="xs"
                        isSkeleton={isSkeleton}
                        label={`${gradedByLabel ?? "Graded by"} ${gradedByModel}`}
                    />
                ),
                ...(modelCategory != null ? [() => (
                    <EnumChip
                        value={modelCategory}
                        map={MODEL_CATEGORY_MAP}
                        isSkeleton={isSkeleton}

                    />
                )] : []),
                ...(timeAgo != null ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={timeAgo}

                    />
                )] : []),
            ]}
        />
    ) : null

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={4}
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <StackH
                                    gap={4}
                                    principle="value-row"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    align="baseline"
                                    at="sm"
                                    isSkeleton={isSkeleton}
                                    items={[
                                        () => (
                                            <Typography
                                                size="h2"
                                                weight="bold"
                                                tabularNums
                                                color={verdictTone}
                                                isSkeleton={isSkeleton}
                                                text={String(score)}

                                            />
                                        ),
                                        ...(maxScore != null ? [() => (
                                            <Typography
                                                size="sm"
                                                color="muted"
                                                tabularNums
                                                isSkeleton={isSkeleton}
                                                text={`/ ${maxScore}`}

                                            />
                                        )] : []),
                                        () => (
                                            <Chip
                                                tone={verdictTone}
                                                icon={isPassing ? CheckCircleIcon : XCircleIcon}
                                                text={isPassing ? "Passed" : "Not yet passed"}
                                                isSkeleton={isSkeleton}

                                            />
                                        ),
                                    ]}
                                />
                            ),
                            ...(pointsNeeded != null && pointsNeeded > 0 ? [() => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={isSkeleton}
                                    text={`Need ${pointsNeeded} more points to reach the ${passScore}-point pass mark`}

                                />
                            )] : []),
                            ...(shortFeedback != null ? [() => (
                                <Typography
                                    size="sm"
                                    isSkeleton={isSkeleton}
                                    text={shortFeedback}

                                />
                            )] : []),
                            ...(submissionUrl != null ? [() => (
                                <Typography
                                    size="sm"
                                    isLink
                                    href={submissionUrl}
                                    isSkeleton={isSkeleton}
                                    text={submissionLabel ?? "View submission"}

                                />
                            )] : []),
                            ...(modelByline != null ? [() => modelByline] : []),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { SubmissionScoreCard }

import React from "react"
