"use client"

import React from "react"
import type { ReactNode } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link LearnBreadcrumb}. */
export interface LearnBreadcrumbProps {
    /**
     * The final (current page) crumb — read-only, no navigation. OMIT on the course-learn home
     * (then `<course>` itself is the last read-only crumb instead of a link).
     */
    current?: ReactNode
    /**
     * Optional intermediate clickable crumb inserted between `<course>` and `current` — for a
     * sub-view of a learn tab (e.g. a flashcard deck under "Review": the section crumb links back
     * to the tab's overview, `current` is the deck name). Only used when `current` is set.
     */
    section?: {
        /** Section label (e.g. "Review"). */
        label: ReactNode
        /** Navigate back to the section overview. */
        onPress: () => void
    }
}

/**
 * Shared page breadcrumb for the course-learn tabs: Home › Courses › <course> › [section ›] {current}.
 *
 * Self-contained (reads the active course from Redux + owns its routing), so any learn page can
 * drop it in — render it INSIDE the page's reading column / `PageHeader` `breadcrumb` slot so it
 * shares that column's padding + cap (no separate padded wrapper). Only the last crumb (+ optional
 * section) varies.
 *
 * @param props - {@link LearnBreadcrumbProps}
 */
export const LearnBreadcrumb = ({ current, section }: LearnBreadcrumbProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)

    const items: Array<ResponsiveBreadcrumbItem> = [
        {
            key: "home",
            label: t("nav.home"),
            onPress: () => router.push(pathConfig().locale().build()),
        },
        {
            key: "courses",
            label: t("nav.courses"),
            onPress: () => router.push(pathConfig().locale(locale).course().build()),
        },
        {
            key: "course",
            label: course?.title || t("nav.courses"),
            // clickable only when it's NOT the current (last read-only) crumb
            onPress: current != null
                ? () => router.push(pathConfig().locale(locale).course(courseDisplayId).build())
                : undefined,
        },
        ...(current != null && section
            ? [{ key: "section", label: section.label, onPress: section.onPress }]
            : []),
        ...(current != null ? [{ key: "current", label: current }] : []),
    ]

    return <ResponsiveBreadcrumb items={items} />
}

export default LearnBreadcrumb

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"

/**
 * `MindMapContinueButton` — the single floating "what's next" action over the
 * course mind-map. `resumeHref` swaps the whole node from a pressable `Button`
 * (with arrow) to an inert `Typography` note — two different atoms — so "resume
 * available" and "all done" are separate shapes; `isSkeleton` is its own too. The
 * real component renders nothing for a guest whose progress has not resolved.
 */

/** Label the block writes itself (§14d.1) — not opened to the caller. */
const CONTINUE_LABEL = "Continue"
/** Quiet confirmation once every lesson/challenge on the map has been read. */
const ALL_DONE_LABEL = "You've completed everything"

/** Props for {@link MindMapContinueButton}. */
export interface MindMapContinueButtonProps {
    /**
 * Href of the viewer's next unread lesson/challenge, or `null` when none
 * resolves. Non-null is the single source of truth for "show the resume
 * pill" — see the file header for why it outranks {@link allContentDone}.
 */
    resumeHref: string | null
    /**
 * `true` -> the viewer has read everything the map has to offer. Only
 * consulted when {@link resumeHref} is `null`; ignored otherwise.
 */
    allContentDone: boolean
    /**
 * Fired on a resume press. Optional: the button itself only renders while
 * {@link resumeHref} is set, so a caller mid-wiring still sees the true shape.
 */
    onResume?: () => void
    /**
 * Accessible name for the resume action, localized by the caller (blocks
 * carry no i18n) — richer than the visible "Continue" label alone, since a
 * screen reader hears it with no page context around it.
 */
    continueAriaLabel: string
    /** `true` -> the block shows its loading shimmer instead of either leaf. */
    isSkeleton?: boolean
}

/**
 * The map's one primary action. See the file header for the three-way
 * precedence and why the two real leaves are two different atoms.
 *
 * @param props - {@link MindMapContinueButtonProps}
 */
const MindMapContinueButton = ({
    resumeHref,
    allContentDone,
    onResume,
    continueAriaLabel,
    isSkeleton = false,
}: MindMapContinueButtonProps) => {
    if (isSkeleton) {
        return (
            <Button
                isSkeleton
                size="lg"
                label={CONTINUE_LABEL}
            />
        )
    }

    if (resumeHref != null) {
        return (
            <Button
                variant="primary"
                size="lg"
                label={CONTINUE_LABEL}
                suffixIcon={ArrowRightIcon}
                iconSlide
                ariaLabel={continueAriaLabel}
                onPress={onResume}
                isElevated
            />
        )
    }

    if (allContentDone) {
        return (
            // TODO(atom): heavy skin-shape (rounded-full + border + bg + shadow — raised pill)
            // should become an atom/composite (Chip/Button/SurfaceCard) — a frame cannot own it,
            // wrap with Box + principles for now.
            <Box
                principle="control-pad" className="rounded-full border border-default bg-surface px-3 py-2 shadow-lg"
                explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
            >
                <Typography
                    size="sm"
                    weight="semibold"
                    color="success"
                    text={ALL_DONE_LABEL}
                />
            </Box>
        )
    }

    // Neither a resolved resume target nor a confirmed "all done" — e.g. a guest
    // whose progress has not loaded into a verdict either way. There is nothing
    // true this block can claim yet, so it renders nothing rather than guessing.
    return null
}

export { MindMapContinueButton }

"use client"

import {
    useCallback,
    useEffect,
    useState,
} from "react"

/** A single entry in the "on this page" outline. */
export interface TocHeading {
    /** Anchor id of the heading element (matches the rendered `id`). */
    id: string
    /** Plain-text label shown in the outline. */
    text: string
    /** Heading depth (2 or 3) used to indent the row. */
    level: number
}

/** Result of {@link useTableOfContents}. */
export interface UseTableOfContentsResult {
    /** The ordered headings discovered in the active lesson body. */
    headings: Array<TocHeading>
    /** Id of the heading currently in view (scroll-spy), or undefined. */
    activeId?: string
    /** Smooth-scroll the article to the given heading id and mark it active. */
    onJump: (id: string) => void
}

/** Id of the lesson article container the outline scans within. */
const ARTICLE_ID = "lesson-article"

/**
 * Builds the "on this page" outline for the active lesson by scanning the rendered
 * article (`#lesson-article [data-toc]`) for heading anchors, then tracks which
 * heading is in view (scroll-spy) and exposes a smooth-scroll jump.
 *
 * DOM-driven (not data-driven) so it works for any rendered body — markdown
 * headings are tagged with `id` + `data-toc` by the shared `MarkdownContent`
 * renderer. Re-scans whenever `rescanKey` changes (lesson navigation / language
 * switch) and while the article subtree mutates (async markdown render).
 *
 * @param rescanKey - A value that changes when the active lesson changes (its id),
 *   forcing a re-scan. Pass `undefined` when no lesson is active.
 * @returns {@link UseTableOfContentsResult} headings, the active id, and a jumper.
 */
export const useTableOfContents = (rescanKey: string | undefined): UseTableOfContentsResult => {
    const [headings, setHeadings] = useState<Array<TocHeading>>([])
    const [activeId, setActiveId] = useState<string | undefined>(undefined)

    // scan the rendered article for heading anchors; re-run on lesson change +
    // while the article subtree mutates (markdown renders client-side, async).
    useEffect(() => {
        let frame = 0

        const scan = () => {
            const container = document.getElementById(ARTICLE_ID)
            if (!container) {
                setHeadings([])
                return
            }
            const nodes = Array.from(container.querySelectorAll<HTMLElement>("[data-toc]"))
            const next = nodes
                .filter((node) => node.id)
                .map((node) => ({
                    id: node.id,
                    // prefer the clean data-toc-label (set by MarkdownContent) so the hover
                    // anchor "#" / inline code in the heading never leaks into the outline.
                    text: node.dataset.tocLabel ?? node.textContent?.trim() ?? "",
                    level: Number(node.dataset.tocLevel ?? "2"),
                }))
            setHeadings(next)
        }

        // coalesce mutation bursts into a single scan per frame.
        const schedule = () => {
            if (frame) {
                return
            }
            frame = requestAnimationFrame(() => {
                frame = 0
                scan()
            })
        }

        // Observe a STABLE root (document.body) instead of polling a fixed number
        // of frames for #lesson-article. On a hard reload the article mounts only
        // after the SWR fetch + markdown render resolves, which can exceed any
        // fixed timeout — the old 60-frame poll then gave up with an empty outline
        // and never re-scanned. body always exists, so we reliably catch both the
        // article mounting and its async heading render, on hard reload AND SPA nav.
        scan()
        const observer = new MutationObserver(schedule)
        observer.observe(document.body, { childList: true, subtree: true })

        return () => {
            if (frame) {
                cancelAnimationFrame(frame)
            }
            observer.disconnect()
        }
    }, [rescanKey])

    // scroll-spy: mark the top-most heading currently in the viewport band.
    useEffect(() => {
        if (headings.length === 0) {
            setActiveId(undefined)
            return
        }
        const elements = headings
            .map((heading) => document.getElementById(heading.id))
            .filter((element): element is HTMLElement => Boolean(element))
        if (elements.length === 0) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                const visible = entries
                    .filter((entry) => entry.isIntersecting)
                    .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)
                if (visible[0]?.target.id) {
                    setActiveId(visible[0].target.id)
                }
            },
            {
                // bias the active band just under the sticky navbar
                rootMargin: "-72px 0px -70% 0px",
                threshold: 0,
            },
        )
        elements.forEach((element) => observer.observe(element))
        return () => observer.disconnect()
    }, [headings])

    const onJump = useCallback((id: string) => {
        const element = document.getElementById(id)
        if (element) {
            element.scrollIntoView({ behavior: "smooth", block: "start" })
            setActiveId(id)
        }
    }, [])

    return {
        headings,
        activeId,
        onJump,
    }
}

import React from "react"
import { StatRibbon, type StatRibbonItem } from "@/components/composites/stats/StatRibbon"

/**
 * `PlaygroundDeviceSnapshot` — "Your machine": the paired agent's raw hardware
 * report turned into the same 4-cell `StatRibbon` the Lab route shows, so setup and
 * the live lab agree about what the machine can run. Reuses `StatRibbon`; the block
 * owns the domain judgement — bytes → GB rounding, the `win32`/`darwin`/`linux` →
 * "Windows"/"macOS"/"Linux" table, and the three sentences a GPU cell can say
 * depending on which of `gpu`/`vramTotalMb`/`vramFreeMb` came back. Every
 * `deviceInfo` combination and `isSkeleton` are states of the 4-cell shape.
 */

/**
 * The paired agent's hardware/OS snapshot, exactly as it arrives over the
 * `device:info` socket message — ported faithfully from
 * `PlaygroundDeviceInfo` in
 * `src/components/features/learn/Playground/PlaygroundPrepare/index.tsx`
 * (itself mirroring `PlaygroundByomDeviceInfoSocketIoMessage`).
 */
export interface PlaygroundDeviceInfo {
    /** `win32` | `linux` | `darwin`. */
    platform: string
    /** CPU architecture (`x64`, `arm64`, …). */
    arch: string
    /** Machine hostname. */
    hostname: string
    /** CPU model string. */
    cpuModel: string
    /** Logical CPU core count. */
    cpuCores: number
    /** Total RAM in bytes. */
    totalMemBytes: number
    /** Free RAM in bytes (at snapshot time). */
    freeMemBytes: number
    /** First discrete GPU name, or `null` if it couldn't be read. */
    gpu: string | null
    /** Free GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramFreeMb?: number
    /** Total GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramTotalMb?: number
}

/** Bytes → whole GB, the unit the ribbon reads in. */
const gbOf = (bytes: number): number => Math.round(bytes / 1e9)

/**
 * Node's `process.platform` id → the name a learner recognises.
 * @param platform - `win32` / `darwin` / `linux` (or anything else, passed through).
 */
const platformLabel = (platform: string): string =>
    platform === "win32"
        ? "Windows"
        : platform === "darwin"
            ? "macOS"
            : platform === "linux" ? "Linux" : platform

/**
 * The GPU cell's detail line: total + free VRAM when the agent could read an
 * NVIDIA card, an empty second line when a GPU exists but VRAM couldn't be
 * read, or an explicit "unknown" when no GPU was detected at all — three
 * distinct facts, not one string with a blank filled in.
 */
const vramDetail = (gpu: string | null, vramTotalMb?: number, vramFreeMb?: number): string =>
    vramTotalMb
        ? `${Math.round(vramTotalMb / 1024)} GB VRAM${vramFreeMb != null ? ` · ${vramFreeMb} MB free` : ""}`
        : gpu ? "" : "couldn't read"

/**
 * One ribbon cell's label: the fixed category word, plus the computed detail
 * when there is one — `StatRibbonItem.label` is a plain `string` (the ribbon
 * renders it itself through `Typography`), so caption and detail join into a
 * single line instead of the old two-line `<span>`.
 */
const deviceStatLabel = (caption: string, detail: string): string =>
    detail ? `${caption} · ${detail}` : caption

/** Props for {@link PlaygroundDeviceSnapshot}. */
export interface PlaygroundDeviceSnapshotProps {
    /** The paired machine's hardware/OS snapshot to render as a stat ribbon. */
    deviceInfo: PlaygroundDeviceInfo
    /** `true` → every cell's value/detail line swaps to its own shimmer. */
    isSkeleton?: boolean
}

/**
 * "Your machine": the paired agent's hardware report as a 4-cell stat ribbon
 * (OS · CPU · RAM · GPU). See the file header for the unit math, the
 * platform-name table, and why this composes `StatRibbon` instead of a new
 * shape.
 *
 * @param props - {@link PlaygroundDeviceSnapshotProps}
 */
const PlaygroundDeviceSnapshot = ({
    deviceInfo,
    isSkeleton = false,
}: PlaygroundDeviceSnapshotProps) => {
    const items: ReadonlyArray<StatRibbonItem> = [
        {
            key: "os",
            value: platformLabel(deviceInfo.platform),
            label: deviceStatLabel("Operating system", `${deviceInfo.arch} · ${deviceInfo.hostname}`),
        },
        {
            key: "cpu",
            value: `${deviceInfo.cpuCores} cores`,
            label: deviceStatLabel("CPU", deviceInfo.cpuModel),
        },
        {
            key: "ram",
            value: `${gbOf(deviceInfo.totalMemBytes)} GB`,
            label: deviceStatLabel("RAM", `${gbOf(deviceInfo.freeMemBytes)} GB free`),
        },
        {
            key: "gpu",
            value: deviceInfo.gpu ?? "—",
            label: deviceStatLabel("GPU", vramDetail(deviceInfo.gpu, deviceInfo.vramTotalMb, deviceInfo.vramFreeMb)),
        },
    ]

    return (
        <StatRibbon
            valueType="body"
            isSkeleton={isSkeleton}
            items={items}
        />
    )
}

export { PlaygroundDeviceSnapshot }

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `PlaygroundHubHeader` — the hub-identity cluster at the top of the
 * Docker/Kubernetes exercise grid: a title and an optional one-sentence purpose
 * line. Sibling of `ContentHeader`/`FoundationsHeader` but thinnest — no breadcrumb,
 * meta row, or secondary card. One shape: `isSkeleton` only swaps which state the
 * `Typography` renders inside the same `PageHeader`.
 */

/** Props for {@link PlaygroundHubHeader}. */
export interface PlaygroundHubHeaderProps {
    /** Hub title, e.g. "Playground". */
    title: string
    /** One-sentence purpose line explaining what the hub is for. */
    description?: string
    /**
     * `true` → the composed `Typography` slots switch to their own shimmer.
     * The flag FLOWS DOWN into the real atoms rather than building a parallel
     * skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The playground-hub identity cluster at the top of the exercise grid. See
 * the file header for the full contract and why this stays thinner than its
 * `ContentHeader`/`FoundationsHeader` siblings.
 *
 * @param props - {@link PlaygroundHubHeaderProps}
 */
const PlaygroundHubHeader = ({
    title,
    description,
    isSkeleton = false,
}: PlaygroundHubHeaderProps) => {
